 IF to_regclass('population_top3000_202608_202609_v1.ctx14_roll_evidence_v6') IS NOT NULL OR to_regprocedure('population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(text)') IS NOT NULL THEN RAISE EXCEPTION 'CTX14_NUMERIC_TEST_EXPECTS_UNINSTALLED_CODE';END IF;
