  started:=clock_timestamp();e:=population_top3000_202608_202609_v1.ctx14_roll_candidate_v6(root);
  WITH bars AS MATERIALIZED(SELECT r.source_id,r.source_ordinal,r.payload->'source_record' raw,r.payload->'parsed' p FROM jsonb_array_elements(e->'source_manifest') src JOIN population_top3000_202608_202609_v1.ctx14_http_record_v3 r ON r.source_id=src->>'source_id' WHERE r.payload->'parsed'->>'root'=root AND r.payload->'parsed'->>'resolution'='1min' AND r.payload->'parsed'->>'session_end_date'='2026-09-11'),paired AS(SELECT o.source_id old_source,o.source_ordinal old_ordinal,o.raw old_raw,z.source_id new_source,z.source_ordinal new_ordinal,z.raw new_raw,o.p->>'window_start_ns' ns FROM bars o JOIN bars z ON o.p->>'window_start_ns'=z.p->>'window_start_ns' WHERE o.p->>'contract_symbol'=root||'U6' AND z.p->>'contract_symbol'=root||'Z6') SELECT * INTO STRICT n FROM paired ORDER BY ns::bigint DESC LIMIT 1;
  IF e#>>'{old,source_id}' IS DISTINCT FROM n.old_source OR e#>>'{new,source_id}' IS DISTINCT FROM n.new_source OR e#>>'{old,source_ordinal}' IS DISTINCT FROM n.old_ordinal::text OR e#>>'{new,source_ordinal}' IS DISTINCT FROM n.new_ordinal::text OR e#>>'{old,ns}' IS DISTINCT FROM n.ns OR e#>>'{new,ns}' IS DISTINCT FROM n.ns OR (e->>'gap_new_minus_old')::numeric IS DISTINCT FROM (n.new_raw->>'close')::numeric-(n.old_raw->>'close')::numeric OR e#>>'{old,raw_record_sha256}' IS DISTINCT FROM encode(sha256(convert_to(n.old_raw::text,'UTF8')),'hex') OR e#>>'{new,raw_record_sha256}' IS DISTINCT FROM encode(sha256(convert_to(n.new_raw::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'CTX14_INDEPENDENT_NUMERICAL_PROJECTION_MISMATCH %',root;END IF;
