 RAISE EXCEPTION USING ERRCODE='P9901',MESSAGE=receipt::text;
 EXCEPTION WHEN SQLSTATE 'P9901' THEN GET STACKED DIAGNOSTICS msg=MESSAGE_TEXT;receipt:=msg::jsonb;
